export const keys=['oil','water','gas','pressure'];
export const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:0;
export const quantile=(a,q)=>{a=[...a].sort((x,y)=>x-y);if(!a.length)return null;const i=(a.length-1)*q;return a[Math.floor(i)]+(a[Math.ceil(i)]-a[Math.floor(i)])*(i%1);};
export function rng(seed=42){return ()=>{seed=(Math.imul(1664525,seed)+1013904223)>>>0;return seed/4294967296;};}
function csvRows(s){const out=[];let row=[],field='',quoted=false;s=s.replace(/^\uFEFF/,'');for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))out.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('CSV引号不闭合');row.push(field);if(row.some(x=>x.trim()))out.push(row);const h=out.shift()?.map(x=>x.trim());if(!h||new Set(h).size!==h.length)throw Error('表头为空或重复');return out.map(r=>Object.fromEntries(h.map((k,i)=>[k,r[i]??''])));}
export function parseData(input){const a=typeof input==='string'?(input.trim().startsWith('[')?JSON.parse(input):csvRows(input)):input;if(!Array.isArray(a)||!a.length||a.length>30000)throw Error('需要1–30000行CSV或JSON数组');const seen=new Set();return a.map((r,i)=>{const id=String(r.well_id??'').trim(),date=String(r.date??'').trim();if(!id||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date)throw Error(`第${i+1}行井号或日期错误`);const k=id+'|'+date;if(seen.has(k))throw Error('重复井号日期：'+k);seen.add(k);const b={well_id:id,date};for(const key of keys){const v=r[key];b[key]=v===null||v===undefined||String(v).trim()===''?null:Number(v);if(b[key]!==null&&(!Number.isFinite(b[key])||b[key]<0))throw Error(`第${i+1}行${key}须为非负数或空值`);}return b;}).sort((a,b)=>a.date.localeCompare(b.date)||a.well_id.localeCompare(b.well_id));}
export function splitRows(rows,ratios=[70,15,15]){if(ratios.length!==3||ratios.some(x=>!Number.isFinite(x)||x<=0)||Math.abs(ratios.reduce((a,b)=>a+b)-100)>1e-6)throw Error('三个比例须大于0且合计100%');const dates=[...new Set(rows.map(r=>r.date))].sort(),n=dates.length,a=Math.floor(n*ratios[0]/100),b=a+Math.floor(n*ratios[1]/100);if(a<12||b<=a||b>=n)throw Error('至少需要连续30日数据并保留三个非空分区');const cut1=dates[a],cut2=dates[b];return {train:rows.filter(r=>r.date<cut1),validation:rows.filter(r=>r.date>=cut1&&r.date<cut2),test:rows.filter(r=>r.date>=cut2)};}
const valid=r=>keys.every(k=>r[k]!==null&&Number.isFinite(r[k]));
function pairs(rows){const by=new Map(),out=[];for(const r of rows){const last=by.get(r.well_id);if(last&&valid(last)&&valid(r)&&Date.parse(r.date)-Date.parse(last.date)===86400000)out.push({x:keys.map(k=>last[k]),y:keys.map(k=>r[k]),row:r,t:Date.parse(r.date)/86400000});by.set(r.well_id,r);}return out;}
const score=(ys,ps)=>{const n=ys.length;if(!n)return {n:0,mae:null,rmse:null,r2:null,bias:null};const avg=mean(ys),e=ys.map((v,i)=>ps[i]-v),sse=e.reduce((s,v)=>s+v*v,0),sst=ys.reduce((s,v)=>s+(v-avg)**2,0);return {n,mae:mean(e.map(Math.abs)),rmse:Math.sqrt(sse/n),r2:sst>1e-12?1-sse/sst:null,bias:mean(e)};};
export function predict(m,x,t){return keys.map((k,j)=>{let y;if(m.id==='ridge'){const [a,b]=m.params.coef[j];y=a+b*x[j];}else if(m.id==='decline'){const [a,b]=m.params.coef[j];y=Math.expm1(Math.max(-20,Math.min(20,a+b*(t-m.params.origin))));}else{const nn=m.params.points.map(p=>({p,d:x.reduce((s,v,i)=>s+((v-p.x[i])/m.params.scale[i])**2,0)})).sort((a,b)=>a.d-b.d).slice(0,m.params.k);y=mean(nn.map(a=>a.p.y[j]));}return Math.max(0,y);});}
function fit(id,ps,h){const params={};if(id==='knn'){params.points=ps.map(({x,y})=>({x,y}));params.scale=keys.map((k,j)=>Math.max(1e-6,Math.sqrt(mean(ps.map(p=>(p.x[j]-mean(ps.map(z=>z.x[j])))**2)))));params.k=h;}else{params.origin=ps[0].t;params.coef=keys.map((k,j)=>{const x=ps.map(p=>id==='ridge'?p.x[j]:p.t-params.origin),y=ps.map(p=>id==='ridge'?p.y[j]:Math.log1p(p.y[j])),mx=mean(x),my=mean(y),variance=x.reduce((s,v)=>s+(v-mx)**2,0),cov=x.reduce((s,v,i)=>s+(v-mx)*(y[i]-my),0),b=cov/(variance+(id==='ridge'?h*Math.max(variance,1):1e-9));return [my-b*mx,b];});}return {id,params};}
function metrics(m,ps){const pred=ps.map(p=>predict(m,p.x,p.t));return Object.fromEntries(keys.map((k,j)=>[k,score(ps.map(p=>p.y[j]),pred.map(p=>p[j]))]));}
function checkPartitions(s){for(const k of ['train','validation','test'])if(!s[k]?.length)throw Error('三个分区均须非空');const max=a=>a.reduce((m,r)=>r.date>m?r.date:m,''),min=a=>a.reduce((m,r)=>r.date<m?r.date:m,'9999');if(max(s.train)>=min(s.validation)||max(s.validation)>=min(s.test))throw Error('训练/验证/测试日期必须严格先后且不重叠');parseData([...s.train,...s.validation,...s.test]);}
export function train(input,options={},partitions=null){const rows=parseData(input),s=partitions?Object.fromEntries(Object.entries(partitions).map(([k,v])=>[k,parseData(v)])):splitRows(rows,options.ratios??[70,15,15]);checkPartitions(s);const ps=Object.fromEntries(Object.entries(s).map(([k,v])=>[k,pairs(v)]));if(ps.train.length<10||ps.validation.length<2||ps.test.length<2)throw Error('完整相邻日样本不足：训练≥10，验证/测试≥2；需补齐四类字段');const models=[];for(const id of ['ridge','decline','knn']){const start=performance.now(),hs=id==='ridge'?[0,.01,.1]:id==='knn'?[3,7,11]:[0];let best=null,bestScore=Infinity;for(const h of hs){const m=fit(id,ps.train,h),ev=metrics(m,ps.validation),v=mean(keys.map(k=>ev[k].rmse/(mean(ps.train.map(p=>p.y[keys.indexOf(k)]))+1e-6)));if(v<bestScore){best=m;bestScore=v;best.hyper=h;}}best.metrics=Object.fromEntries(Object.entries(ps).map(([k,v])=>[k,metrics(best,v)]));best.duration=(performance.now()-start)/1000;best.validationScore=bestScore;best.residuals=ps.validation.map(p=>{const y=predict(best,p.x,p.t);return p.y.map((v,j)=>v-y[j]);});best.results=Object.fromEntries(Object.entries(ps).map(([k,v])=>[k,v.map(p=>({date:p.row.date,well_id:p.row.well_id,actual:p.y,predicted:predict(best,p.x,p.t)}))]));models.push(best);}return {models,splits:s,counts:Object.fromEntries(Object.entries(ps).map(([k,v])=>[k,v.length])),best:models.toSorted((a,b)=>a.validationScore-b.validationScore)[0].id};}
export function forecast(fitted,history,days=60,id=fitted.best,seed=42){if(!Number.isInteger(days)||days<1||days>180)throw Error('预测天数1–180');const m=fitted.models.find(m=>m.id===id);if(!m)throw Error('请先训练模型');const h=parseData(history);if(new Set(h.map(r=>r.well_id)).size!==1)throw Error('预测须选择单井');const last=h.at(-1);const trained=fitted.splits.train.filter(r=>r.well_id===last.well_id).at(-1);if(!trained)throw Error('该井没有训练样本');if(last.date<trained.date)throw Error('预测起点早于训练截止日期');if(!valid(last))throw Error('最新记录缺少油/水/气/压力，请补齐后预测');const rand=rng(seed),paths=Array.from({length:120},()=>keys.map(k=>last[k])),out=[];let centre=keys.map(k=>last[k]);for(let d=1;d<=days;d++){const t=Date.parse(last.date)/86400000+d;centre=predict(m,centre,t);for(let n=0;n<paths.length;n++){const pred=predict(m,paths[n],t),e=m.residuals[Math.floor(rand()*m.residuals.length)];paths[n]=pred.map((v,j)=>Math.max(0,v+e[j]));}const r={day:d,date:new Date(t*86400000).toISOString().slice(0,10)};for(let j=0;j<4;j++){const values=paths.map(p=>p[j]);r[keys[j]]={low:Math.min(centre[j],quantile(values,.1)),mid:centre[j],high:Math.max(centre[j],quantile(values,.9))};}const ratios=paths.filter(p=>p[1]>1e-9).map(p=>p[0]/p[1]);r.owr={low:quantile(ratios,.1),mid:centre[1]>1e-9?centre[0]/centre[1]:null,high:quantile(ratios,.9)};if(r.owr.mid!==null&&ratios.length){r.owr.low=Math.min(r.owr.low,r.owr.mid);r.owr.high=Math.max(r.owr.high,r.owr.mid);}out.push(r);}return out;}
export function analogues(cases,p,k=5){const fields=['permeability','porosity','thickness','watercut'];return cases.filter(c=>fields.every(f=>Number.isFinite(c[f]))).map(c=>({...c,distance:Math.sqrt(fields.reduce((s,f)=>s+((c[f]-p[f])/({permeability:100,porosity:.1,thickness:10,watercut:30}[f]))**2,0))})).sort((a,b)=>a.distance-b.distance).slice(0,k);}
